import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { generatePkgConfig } from './source/packages/cli/src/lib/packer/pkg-config-generator.js';
const audit=fileURLToPath(new URL('./',import.meta.url));
const repo=path.join(audit,'source');
const base=path.join(audit,'variants');
const variant=process.argv[2]||'valid';
const cliRoot=path.join(base,variant);
fs.mkdirSync(cliRoot,{recursive:true});
fs.writeFileSync(path.join(cliRoot,'package.json'),JSON.stringify({name:'cc-helper-probe',version:'1.0.0',type:'module',license:'MIT'}));
for(const name of ['linux-subreaper-helper.js','linux-subreaper-process.js','linux-subreaper-artifact.js','linux-subreaper-supervisor.c']){
 const rel='src/lib/process-execution-broker/'+name;fs.mkdirSync(path.dirname(path.join(cliRoot,rel)),{recursive:true});fs.copyFileSync(path.join(repo,'packages/cli',rel),path.join(cliRoot,rel));
}
for(const name of ['mcp-stdio-capsule-builder-worker.cjs','mcp-stdio-immutable-vfs-resolver.cjs'])fs.copyFileSync(path.join(repo,'packages/cli/src/lib',name),path.join(cliRoot,'src/lib',name));
const require=createRequire(path.join(repo,'packages/cli/package.json'));
const esbuild=path.dirname(require.resolve('esbuild-wasm/package.json'));
for(const name of ['package.json','lib/browser.js','esbuild.wasm']){
 const dst=path.join(cliRoot,'node_modules/esbuild-wasm',name);fs.mkdirSync(path.dirname(dst),{recursive:true});fs.copyFileSync(path.join(esbuild,name),dst);
}
fs.cpSync(path.join(audit,'helper-build'),path.join(cliRoot,'src/assets/linux-subreaper'),{recursive:true});
const result=generatePkgConfig({cliRoot,tempDir:path.join(cliRoot,'temp'),distDir:path.join(cliRoot,'web'),templatesDir:path.join(cliRoot,'templates'),targets:['node22-linux-x64'],outputPath:path.join(cliRoot,'probe'),compress:true});
const config=JSON.parse(fs.readFileSync(result.pkgConfigFile,'utf8'));
config.bin=path.join(cliRoot,'probe.cjs');
config.pkg.assets=config.pkg.assets.filter(asset=>fs.existsSync(path.resolve(result.pkgConfigDir,asset)));
if(variant==='missing')config.pkg.assets=config.pkg.assets.filter(asset=>!asset.endsWith('manifest.json'));
if(variant==='corrupt')fs.appendFileSync(path.join(cliRoot,'src/assets/linux-subreaper/linux-x64/supervisor'),'corrupt');
if(variant==='source')fs.appendFileSync(path.join(cliRoot,'src/lib/process-execution-broker/linux-subreaper-supervisor.c'),'corrupt');
fs.copyFileSync(path.join(audit,'probe.cjs'),path.join(cliRoot,'probe.cjs'));
fs.writeFileSync(result.pkgConfigFile,JSON.stringify(config,null,2));
console.log(JSON.stringify({variant,...result,cliRoot}));

const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const { acquireLinuxSubreaperHelper } = require('./src/lib/process-execution-broker/linux-subreaper-helper.js');
const { spawnLinuxSubreaperChild } = require('./src/lib/process-execution-broker/linux-subreaper-process.js');
let compilerCalls = 0;
const failures=[];
for(const name of ['realpathSync','lstatSync','openSync','fstatSync','readlinkSync']) {
 const original=fs[name];fs[name]=function(...args){try{return original.apply(this,args);}catch(error){failures.push({name,arg:args[0],code:error.code});throw error;}};
}
(async () => {
  let mounted;
  if(path.basename(__dirname)==='mounted') {
    const original=path.join(__dirname,'src/assets/linux-subreaper/linux-x64');
    mounted=fs.mkdtempSync(path.join(os.tmpdir(),'cc-standalone-mounted-'));
    for(const name of ['manifest.json','supervisor'])fs.writeFileSync(path.join(mounted,name),fs.readFileSync(path.join(original,name)));
    process.pkg.mount(original,mounted);
  }
  let helper;
  try { helper = acquireLinuxSubreaperHelper({ spawnSync() { compilerCalls++; throw new Error('compiler forbidden'); } }); }
  catch (error) { console.log(JSON.stringify({ rejected:true, code:error.code, message:error.message, compilerCalls, pkg:!!process.pkg, failures, entry:process.pkg.defaultEntrypoint, root:__dirname }));if(mounted){for(const name of ['manifest.json','supervisor'])fs.unlinkSync(path.join(mounted,name));fs.rmdirSync(mounted);} process.exitCode=3; return; }
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'cc-native-helper-probe-'));
  const target=path.join(root,'tree.cjs');
  fs.writeFileSync(target, `const {spawn}=require('node:child_process');process.on('SIGTERM',()=>{});setTimeout(()=>process.exit(0),5000);if(process.argv[2]==='leaf')process.send({pid:process.pid});else{const leaf=spawn(process.execPath,[__filename,'leaf'],{detached:true,stdio:['ignore','ignore','ignore','ipc']});leaf.once('message',({pid})=>process.stdout.write(JSON.stringify([process.pid,pid])+'\\n'));}`);
  let binding, replacement, child, timer;
  try {
    child=spawnLinuxSubreaperChild(process.argv[2],[target],{helper,cwd:root,env:{},graceMs:100},{spawn(command,args,options){
      const fd=options.stdio[4];const st=fs.fstatSync(fd);const linked=fs.readlinkSync('/proc/self/fd/'+fd);
      assert.equal(command,'/proc/self/fd/4');assert.equal(st.nlink,0);assert.equal(st.mode&0o777,0o500);
      replacement=linked.replace(/ \(deleted\)$/,'');
      assert.ok(replacement.startsWith(os.tmpdir()+'/cc-linux-subreaper-build-'));
      fs.mkdirSync(path.dirname(replacement));fs.writeFileSync(replacement,'#!/bin/sh\nexit 99\n',{mode:0o700});
      binding={command,nlink:st.nlink,mode:st.mode&0o777,replacementCreated:true};
      return spawn(command,args,options);
    }});
    const errors=[];child.on('error',e=>errors.push(e.code));child.stderr.resume();let text='';let pids;let start;
    child.stdout.on('data',chunk=>{text+=chunk;if(!pids&&text.includes('\n')){pids=JSON.parse(text.trim());start=performance.now();child.kill('SIGTERM');child.kill('SIGTERM');}});
    const receipt=await Promise.race([child.ownedProcessTreeClosed,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('timeout')),8000);})]);
    assert.deepEqual(errors,[]);assert.equal(pids?.length,2);assert.equal(receipt.cleanup.confirmed,true);assert.equal(receipt.cleanup.reaped,2);assert.equal(receipt.helper.binding,'unlinked-inherited-fd');assert.equal(compilerCalls,0);
    for(const pid of pids)assert.equal(fs.existsSync('/proc/'+pid),false);
    console.log(JSON.stringify({schema:'cc-standalone-helper-probe/v1',pkg:!!process.pkg,node:process.version,compilerCalls,binding,pids,elapsedAfterReadyMs:performance.now()-start,receipt}));
  } finally {clearTimeout(timer);child?.kill('SIGKILL');fs.unlinkSync(target);fs.rmdirSync(root);if(replacement){fs.unlinkSync(replacement);fs.rmdirSync(path.dirname(replacement));}}
})().catch(error=>{console.error(error.stack);process.exitCode=1;});

const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');
const root=path.join(__dirname,'variants');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const base=fs.readFileSync(path.join(root,'valid/cc-helper-probe-pack'));
const result={baseSha:sha(base),variants:[]};
for(const variant of ['missing','corrupt','source','mounted']){
 const bytes=fs.readFileSync(path.join(root,variant,'cc-helper-probe-pack'));const chunks=[];
 for(let i=0;i<bytes.length;){if(i<base.length&&base[i]===bytes[i]){i++;continue;}const begin=i;let last=i;i++;
 while(i<bytes.length){if(i>=base.length||base[i]!==bytes[i])last=i;if(i-last>1024)break;i++;}
 const end=Math.min(bytes.length,last+1);chunks.push({offset:begin,data:bytes.subarray(begin,end).toString('base64')});i=end;}
 result.variants.push({variant,bytes:bytes.length,sha:sha(bytes),chunks});
}
fs.writeFileSync(path.join(__dirname,'patches.json'),JSON.stringify(result));console.log(JSON.stringify(result.variants.map(x=>({variant:x.variant,bytes:x.bytes,sha:x.sha,patchBytes:x.chunks.reduce((s,c)=>s+c.data.length,0)}))));

const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');const assert=require('node:assert/strict');const {spawnSync}=require('node:child_process');
const root=fs.realpathSync(__dirname);
assert.match(root,/^\/tmp\/cc-standalone-b776be5fc8-[A-Za-z0-9]{8}$/);
const base=path.join(root,'valid');const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const patch=JSON.parse(fs.readFileSync(path.join(root,'patches.json'),'utf8'));
assert.equal(sha(fs.readFileSync(base)),patch.baseSha);
const temporary=path.join(root,'tmp');fs.mkdirSync(temporary,{mode:0o700});
const expected={missing:'standalone-asset-missing',corrupt:'packaged-identity-mismatch',source:'source-digest-mismatch',mounted:'standalone-asset-not-embedded'};
const results=[];
for(const value of [{variant:'valid',sha:patch.baseSha},...patch.variants]){
 assert.ok(value.variant==='valid'||Object.hasOwn(expected,value.variant));
 const file=path.join(root,value.variant);
 if(value.variant!=='valid'){
  fs.copyFileSync(base,file);const fd=fs.openSync(file,'r+');
  try{fs.ftruncateSync(fd,value.bytes);for(const chunk of value.chunks){const bytes=Buffer.from(chunk.data,'base64');fs.writeSync(fd,bytes,0,bytes.length,chunk.offset);}}finally{fs.closeSync(fd);}
 }
 assert.equal(sha(fs.readFileSync(file)),value.sha);fs.chmodSync(file,0o700);
 const run=spawnSync('/usr/bin/timeout',['12',file,'/usr/bin/node'],{cwd:root,env:{PATH:'/usr/bin:/bin',TMPDIR:temporary},encoding:'utf8',timeout:15000,maxBuffer:1024*1024});
 const result={variant:value.variant,sha256:'sha256:'+value.sha,bytes:fs.statSync(file).size,status:run.status,signal:run.signal,error:run.error?.code||null,stdout:run.stdout,stderr:run.stderr};results.push(result);
 fs.writeFileSync(path.join(root,'probe-results.json'),JSON.stringify({schema:'cc-exact-sha-standalone-native-results/v1',host:process.platform,arch:process.arch,node:process.version,results},null,2)+'\n');
 assert.equal(run.signal,null);assert.equal(run.error,undefined);assert.equal(run.stderr,'');
 const output=JSON.parse(run.stdout);assert.equal(output.pkg,true);assert.equal(output.compilerCalls,0);
 if(value.variant==='valid'){
  assert.equal(run.status,0);assert.equal(output.binding.command,'/proc/self/fd/4');assert.equal(output.binding.nlink,0);assert.equal(output.binding.mode,0o500);assert.equal(output.binding.replacementCreated,true);
  assert.equal(output.receipt.cleanup.confirmed,true);assert.equal(output.receipt.cleanup.reaped,2);assert.equal(output.receipt.helper.binding,'unlinked-inherited-fd');assert.equal(output.receipt.helper.distribution,'packaged-static');
 }else{
  assert.equal(run.status,3);assert.equal(output.rejected,true);assert.equal(output.code,'EXTERNAL_AGENT_HELPER_UNAVAILABLE');assert.ok(output.message.endsWith(expected[value.variant]));
 }
 console.log(JSON.stringify({variant:value.variant,status:run.status,verified:true}));
}
assert.deepEqual(fs.readdirSync(temporary),[]);
console.log(JSON.stringify({status:'verified',variants:results.length,temporaryDirectoryEmpty:true}));

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
const base=fileURLToPath(new URL('./',import.meta.url));
const source=path.join(base,'source');
const commit='b776be5fc8bb8fd04d9a6ef2846eaf61bac8f4f0';
const hash=b=>'sha256:'+crypto.createHash('sha256').update(b).digest('hex');
function walk(root){return fs.readdirSync(root,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(root,e.name)):[path.join(root,e.name)]);}
const files=walk(source).sort().map(file=>{
 const relative=path.relative(source,file).replaceAll('\\','/');
 const bytes=fs.readFileSync(file);
 const committed=execFileSync('git',['show',commit+':'+relative],{maxBuffer:4*1024*1024});
 assert.ok(bytes.equals(committed),relative);
 return {path:relative,bytes:bytes.length,sha256:hash(bytes),matchesCommit:true};
});
assert.equal(files.length,9);
const result={commit,scope:'nine archived input source files; exact Git blob byte comparison',sourceClean:true,archiveSha256:hash(fs.readFileSync(path.join(base,'source.tar'))),files};
fs.writeFileSync(path.join(base,'source-'+process.argv[2]+'.json'),JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({phase:process.argv[2],commit,sourceClean:true,files:files.length}));
